import { initTRPC } from '@trpc/server';
import { createHTTPServer } from '@trpc/server/adapters/standalone';
import { z } from 'zod';

const t = initTRPC.create();
const publicProcedure = t.procedure;
const router = t.router;

const appRouter = router({
  countdown: publicProcedure
    .input(z.number())
    .subscription(async function* ({ input }: { input: number }) {
      for (let i = input; i >= 0; i--) {
        yield i;
        await new Promise((resolve) => setTimeout(resolve, 100));
      }
    }),
});

export type AppRouter = typeof appRouter;

const server = createHTTPServer({
  router: appRouter,
});

server.listen(3000);

import { createTRPCClient } from '@trpc/client';
import { httpSubscriptionLink } from '@trpc/client';
import fs from 'fs';
import type { AppRouter } from './server';

const trpc = createTRPCClient<AppRouter>({
  links: [
    httpSubscriptionLink({
      url: 'http://localhost:3000',
    }),
  ],
});

async function main() {
  const results: number[] = [];

  const subscription = trpc.countdown.subscribe(3, {
    onData: (value: number) => {
      results.push(value);
    },
  });

  await subscription.complete;

  fs.writeFileSync('/home/user/project/output.json', JSON.stringify(results));
  console.log('Wrote output.json:', results);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

